    insert into public.atividades (aula_id, ordem, pergunta, tipo, razao) values

    (v_aula_id, 1, $p$Lewis descreve a Queda como o movimento da criatura que tenta "ser seu próprio dono", dizer a Deus "este negócio é nosso e não seu", embora não sejamos donos nem de nós mesmos; em que cantos da sua vida você ainda reivindica um território "seu", fora do alcance de Deus, e o que isso tem produzido em você?$p$, 'reflexao', null),
    (v_aula_id, 2, $p$Ele observa que todos os dias, antes mesmo de terminarmos a barba, o novo dia que entregamos a Deus ao acordar volta a ser "o nosso dia", e a participação dEle passa a parecer uma dedução do tempo que sentimos ser "nosso"; como você percebe esse deslizamento diário do "para Deus" para o "para mim", e o que ajudaria você a recomeçar a entrega a cada manhã?$p$, 'reflexao', null),
    (v_aula_id, 3, $p$Lewis diz que nossa condição é de "pecado original", e não apenas de "infortúnio original", e usa a imagem do menino mal-educado adotado por uma família decente, cujo caráter detestável não é mera "infelicidade", mas ele mesmo; em vez de tratar suas falhas como azar ou herança da qual você é só vítima, como mudaria sua oração reconhecê-las como parte real de quem você é diante de um Deus que quer transformá-lo?$p$, 'reflexao', null);
